// src/pages/Perfil.jsx
import React, { useState, useEffect } from "react";
import { updateUserProfile, uploadUserPhoto, deleteUserPhoto } from "../firebase";
import { useNavigate } from "react-router-dom";

export default function Perfil({ user, profile, onProfileUpdate }) {
  const [editing, setEditing] = useState(false);
  const [formData, setFormData] = useState({
    name: "",
    surname: "",
    phone: "",
    dob: "",
    alias: ""
  });
  const [loading, setLoading] = useState(false);
  const [uploadingPhoto, setUploadingPhoto] = useState(false);
  const [showPhotoModal, setShowPhotoModal] = useState(false);
  const nav = useNavigate();

  // Verificar si el perfil está incompleto
  const isIncomplete = !profile?.name || !profile?.surname || !profile?.phone || !profile?.dob;

  useEffect(() => {
    if (profile) {
      setFormData({
        name: profile.name || "",
        surname: profile.surname || "",
        phone: profile.phone || "",
        dob: profile.dob || "",
        alias: profile.alias || ""
      });
      // Si el perfil está incompleto, activar automáticamente el modo de edición
      if (isIncomplete) {
        setEditing(true);
      }
    }
  }, [profile, isIncomplete]);

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    // Validar que todos los campos estén completos
    if (!formData.name || !formData.surname || !formData.phone || !formData.dob) {
      alert("Todos los campos son obligatorios. Por favor, completa tu perfil.");
      return;
    }
    
    setLoading(true);
    try {
      await updateUserProfile(user.uid, formData);
      alert("Perfil actualizado correctamente");
      setEditing(false);
      // Recargar perfil
      if (onProfileUpdate) {
        await onProfileUpdate();
      }
      // Si el perfil estaba incompleto y ahora está completo, redirigir al menú
      if (isIncomplete) {
        nav("/menu");
      }
    } catch (err) {
      console.error("Error actualizando perfil:", err);
      alert("Error actualizando perfil: " + (err.message || err));
    } finally {
      setLoading(false);
    }
  };

  const handleCancel = () => {
    // Restaurar valores originales
    setFormData({
      name: profile?.name || "",
      surname: profile?.surname || "",
      phone: profile?.phone || "",
      dob: profile?.dob || "",
      alias: profile?.alias || ""
    });
    setEditing(false);
  };

  const handlePhotoChange = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;

    // Validar tamaño (máximo 5MB)
    if (file.size > 5 * 1024 * 1024) {
      alert("La imagen no puede superar los 5MB");
      return;
    }

    // Validar tipo
    if (!file.type.startsWith('image/')) {
      alert("Solo se permiten archivos de imagen");
      return;
    }

    setUploadingPhoto(true);
    try {
      await uploadUserPhoto(user.uid, file);
      alert("Foto actualizada correctamente");
      if (onProfileUpdate) {
        onProfileUpdate();
      }
    } catch (err) {
      console.error("Error subiendo foto:", err);
      alert("Error al subir la foto: " + (err.message || err));
    } finally {
      setUploadingPhoto(false);
    }
  };

  const handleDeletePhoto = async () => {
    if (!window.confirm("¿Estás seguro de que quieres eliminar tu foto de perfil?")) {
      return;
    }

    setUploadingPhoto(true);
    try {
      await deleteUserPhoto(user.uid);
      alert("Foto eliminada correctamente");
      if (onProfileUpdate) {
        onProfileUpdate();
      }
    } catch (err) {
      console.error("Error eliminando foto:", err);
      alert("Error al eliminar la foto: " + (err.message || err));
    } finally {
      setUploadingPhoto(false);
    }
  };

  return (
    <div style={{ padding: 16, maxWidth: 600, margin: "0 auto" }}>
      <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 24 }}>
        <h2 style={{ margin: 0 }}>Mi Perfil</h2>
      </div>

      {isIncomplete && (
        <div style={{
          background: '#fff3cd',
          border: '2px solid #ffc107',
          borderRadius: '8px',
          padding: '16px',
          marginBottom: 20,
          color: '#856404'
        }}>
          <strong>⚠️ Perfil incompleto</strong>
          <p style={{ margin: '8px 0 0 0', fontSize: 14 }}>
            Debes completar todos los campos de tu perfil para poder usar la aplicación.
          </p>
        </div>
      )}

      {!editing ? (
        <div className="card" style={{ padding: 20 }}>
          {/* Foto de perfil */}
          <div style={{ marginBottom: 24, textAlign: 'center' }}>
            <div style={{ 
              width: 120, 
              height: 120, 
              borderRadius: '50%', 
              overflow: 'hidden',
              margin: '0 auto 16px',
              background: profile?.photoURL ? 'transparent' : 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              border: '4px solid #e5e7eb',
              cursor: profile?.photoURL ? 'pointer' : 'default'
            }}
            onClick={() => profile?.photoURL && setShowPhotoModal(true)}
            >
              {profile?.photoURL ? (
                <img 
                  src={profile.photoURL} 
                  alt="Foto de perfil" 
                  style={{ width: '100%', height: '100%', objectFit: 'cover' }}
                />
              ) : (
                <span style={{ fontSize: 48, color: '#fff' }}>
                  {profile?.name?.charAt(0)?.toUpperCase() || '👤'}
                </span>
              )}
            </div>
            
            <div style={{ display: 'flex', gap: 8, justifyContent: 'center', flexWrap: 'wrap' }}>
              <label style={{
                padding: '8px 16px',
                background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
                color: '#fff',
                borderRadius: 8,
                cursor: uploadingPhoto ? 'not-allowed' : 'pointer',
                fontSize: 14,
                fontWeight: 600,
                opacity: uploadingPhoto ? 0.6 : 1
              }}>
                {uploadingPhoto ? '⏳ Subiendo...' : '📷 Cambiar foto'}
                <input 
                  type="file" 
                  accept="image/*"
                  onChange={handlePhotoChange}
                  disabled={uploadingPhoto}
                  style={{ display: 'none' }}
                />
              </label>
              
              {profile?.photoURL && (
                <button
                  onClick={handleDeletePhoto}
                  disabled={uploadingPhoto}
                  style={{
                    padding: '8px 16px',
                    background: '#ef4444',
                    color: '#fff',
                    border: 'none',
                    borderRadius: 8,
                    cursor: uploadingPhoto ? 'not-allowed' : 'pointer',
                    fontSize: 14,
                    fontWeight: 600,
                    opacity: uploadingPhoto ? 0.6 : 1
                  }}
                >
                  🗑️ Eliminar
                </button>
              )}
            </div>
          </div>

          <div style={{ marginBottom: 20 }}>
            <div style={{ fontSize: 13, color: "#666", marginBottom: 4 }}>Email</div>
            <div style={{ fontSize: 16, fontWeight: 600 }}>{user?.email}</div>
          </div>

          <div style={{ marginBottom: 20 }}>
            <div style={{ fontSize: 13, color: "#666", marginBottom: 4 }}>Nombre</div>
            <div style={{ fontSize: 16, fontWeight: 600 }}>{profile?.name || "Sin nombre"}</div>
          </div>

          <div style={{ marginBottom: 20 }}>
            <div style={{ fontSize: 13, color: "#666", marginBottom: 4 }}>Apellidos</div>
            <div style={{ fontSize: 16, fontWeight: 600 }}>{profile?.surname || "Sin apellidos"}</div>
          </div>

          <div style={{ marginBottom: 20 }}>
            <div style={{ fontSize: 13, color: "#666", marginBottom: 4 }}>Alias (nombre corto)</div>
            <div style={{ fontSize: 16, fontWeight: 600 }}>{profile?.alias || "Sin alias"}</div>
          </div>

          <div style={{ marginBottom: 20 }}>
            <div style={{ fontSize: 13, color: "#666", marginBottom: 4 }}>Teléfono</div>
            <div style={{ fontSize: 16, fontWeight: 600 }}>{profile?.phone || "Sin teléfono"}</div>
          </div>

          <div style={{ marginBottom: 20 }}>
            <div style={{ fontSize: 13, color: "#666", marginBottom: 4 }}>Fecha de nacimiento</div>
            <div style={{ fontSize: 16, fontWeight: 600 }}>
              {profile?.dob ? new Date(profile.dob).toLocaleDateString() : "Sin fecha"}
            </div>
          </div>

          {!isIncomplete && (
            <button 
              className="btn-primary full" 
              onClick={() => setEditing(true)}
              style={{ marginTop: 20 }}
            >
              ✏️ Editar perfil
            </button>
          )}
          
          {isIncomplete && (
            <button 
              className="btn-primary full" 
              onClick={() => setEditing(true)}
              style={{ marginTop: 20, background: '#ffc107', color: '#000' }}
            >
              ⚠️ Completar perfil obligatorio
            </button>
          )}
        </div>
      ) : (
        <form onSubmit={handleSubmit} className="card" style={{ padding: 20 }}>
          <div style={{ marginBottom: 16 }}>
            <label style={{ display: "block", fontSize: 13, marginBottom: 4, color: "#666" }}>
              Email (no editable)
            </label>
            <input
              type="text"
              value={user?.email}
              disabled
              className="full-input"
              style={{ background: "#f5f5f5", cursor: "not-allowed" }}
            />
          </div>

          <div style={{ marginBottom: 16 }}>
            <label style={{ display: "block", fontSize: 13, marginBottom: 4 }}>
              Nombre *
            </label>
            <input
              type="text"
              name="name"
              value={formData.name}
              onChange={handleChange}
              required
              className="full-input"
              placeholder="Introduce tu nombre"
            />
          </div>

          <div style={{ marginBottom: 16 }}>
            <label style={{ display: "block", fontSize: 13, marginBottom: 4 }}>
              Apellidos *
            </label>
            <input
              type="text"
              name="surname"
              value={formData.surname}
              onChange={handleChange}
              required
              className="full-input"
              placeholder="Introduce tus apellidos"
            />
          </div>

          <div style={{ marginBottom: 16 }}>
            <label style={{ display: "block", fontSize: 13, marginBottom: 4 }}>
              Alias (nombre corto)
            </label>
            <input
              type="text"
              name="alias"
              value={formData.alias}
              onChange={handleChange}
              className="full-input"
              placeholder="Ej: Pepe, Juan, Ana..."
              maxLength="15"
            />
            <small style={{ fontSize: 11, color: '#666', display: 'block', marginTop: 4 }}>
              Nombre corto para mostrarse en listas
            </small>
          </div>

          <div style={{ marginBottom: 16 }}>
            <label style={{ display: "block", fontSize: 13, marginBottom: 4 }}>
              Teléfono *
            </label>
            <input
              type="tel"
              name="phone"
              value={formData.phone}
              onChange={handleChange}
              required
              className="full-input"
              placeholder="Introduce tu teléfono"
            />
          </div>

          <div style={{ marginBottom: 20 }}>
            <label style={{ display: "block", fontSize: 13, marginBottom: 4 }}>
              Fecha de nacimiento *
            </label>
            <input
              type="date"
              name="dob"
              value={formData.dob}
              onChange={handleChange}
              required
              className="full-input"
            />
          </div>

          <div style={{ display: "flex", gap: 8 }}>
            <button 
              type="submit" 
              className="btn-primary" 
              disabled={loading}
              style={{ flex: 1 }}
            >
              {loading ? "Guardando..." : "💾 Guardar cambios"}
            </button>
            {!isIncomplete && (
              <button 
                type="button" 
                className="btn-ghost" 
                onClick={handleCancel}
                disabled={loading}
                style={{ flex: 1 }}
              >
                ❌ Cancelar
              </button>
            )}
          </div>
        </form>
      )}

      {/* Modal para maximizar foto */}
      {showPhotoModal && profile?.photoURL && (
        <div 
          style={{
            position: 'fixed',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            backgroundColor: 'rgba(0, 0, 0, 0.9)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            zIndex: 9999,
            padding: 20,
            cursor: 'pointer'
          }}
          onClick={() => setShowPhotoModal(false)}
        >
          <img 
            src={profile.photoURL} 
            alt="Foto de perfil ampliada" 
            style={{
              maxWidth: '90%',
              maxHeight: '90%',
              objectFit: 'contain',
              borderRadius: 8,
              boxShadow: '0 8px 32px rgba(0, 0, 0, 0.5)'
            }}
          />
        </div>
      )}
    </div>
  );
}
